// node stories/new-stories.mjs [ids…]: only the named stories, so earlier hand-fixed JSONs are never overwritten
const only = process.argv.slice(2);
for (const [id, s] of Object.entries(STORIES).filter(([id]) => !only.length || only.includes(id))) {
  const scenes = s.scenes.map(([k, kw, feel, pace, img, text], i) => Object.assign({ k, kw, feel, pace }, img && { img }, { text }, i === 0 && { score: s.score }));
  writeFileSync(new URL(`./${id}.json`, import.meta.url), JSON.stringify({ id, title: s.title, voice: 'chandrika_en_stories', scenes }, null, 2) + '\n');
  console.log(id, scenes.length, 'scenes,', scenes.filter((x) => x.img).length, 'new paintings');
}
